+
+var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
+
+IChatClient chatClient = new OpenAIClient(apiKey)
+    .GetChatClient(modelId)
+    .AsIChatClient();
+
+var tools = new[]
+{
+    AIFunctionFactory.Create(ResearchTools.WebSearch),
+    AIFunctionFactory.Create(ResearchTools.SaveNote),
+    AIFunctionFactory.Create(ResearchTools.GetNotes),
+};
+
+var chatOptions = new ChatOptions
+{
+    Tools = [.. tools],
+    ToolMode = ChatToolMode.Auto
+};
+
+var systemPrompt = """
+    You are a research agent. Your job is to research a topic thoroughly and produce
+    a clear summary. Follow these steps:
+    1. Use the WebSearch tool to find information about the topic.
+    2. Use the SaveNote tool to record key findings as you go.
+    3. Perform additional searches to fill gaps or explore subtopics.
+    4. Use GetNotes to review everything you have collected.
+    5. Finally, produce a well-structured summary of your research.
+    Be thorough but concise. Cite key facts and figures where available.
+    """;
+
+var topic = args.Length > 0
+    ? string.Join(' ', args)
+    : "quantum computing";
+
+Console.WriteLine($"🤖 Research Agent Starting...");
+Console.WriteLine($"📚 Topic: {topic}\n");
+
+List<ChatMessage> messages =
+[
+    new(ChatRole.System, systemPrompt),
+    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
+];
+
+// Agent loop: keep calling the model until it produces a final answer with no tool calls.
+const int maxIterations = 15;
+for (var i = 0; i < maxIterations; i++)
+{
+    var response = await chatClient.GetResponseAsync(messages, chatOptions);
+
+    // Append the full response (including any tool-call content) to the conversation.
+    messages.AddMessages(response);
+
+    // Check whether the model invoked any tools.
+    var functionCalls = response.Messages
+        .SelectMany(m => m.Contents)
+        .OfType<FunctionCallContent>()
+        .ToList();
+
+    if (functionCalls.Count == 0)
+    {
+        // No tool calls – the model produced its final answer.
+        var answer = response.Messages
+            .SelectMany(m => m.Contents)
+            .OfType<TextContent>()
+            .LastOrDefault();
+
+        Console.WriteLine("\n════════════════════════════════════════════");
+        Console.WriteLine("  RESEARCH SUMMARY");
+        Console.WriteLine("════════════════════════════════════════════\n");
+        Console.WriteLine(answer?.Text ?? "(no summary produced)");
+        break;
+    }
+
+    // Execute each tool call and feed results back to the model.
+    foreach (var fc in functionCalls)
+    {
+        var tool = tools.FirstOrDefault(t => t.Name == fc.Name);
+        if (tool is null)
+        {
+            messages.Add(new ChatMessage(ChatRole.Tool,
+                [new FunctionResultContent(fc.CallId, fc.Name, "Unknown tool.")]));
+            continue;
+        }
+
+        var result = await tool.InvokeAsync(fc.Arguments);
+        messages.Add(new ChatMessage(ChatRole.Tool,
+            [new FunctionResultContent(fc.CallId, fc.Name, result)]));
+    }
+}
+
+Console.WriteLine("\n✅ Research complete.");

