using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool implementations ---------------------------------------------------

/// <summary>Tools the research agent can invoke during its reasoning loop.</summary>
static class ResearchTools
{
    private static readonly List<(string Topic, string Note)> _notes = [];

    [Description("Search the web for a query and return relevant result snippets.")]
    public static string WebSearch([Description("The search query")] string query)
    {
        Console.WriteLine($"  🔍  Searching the web for: \"{query}\"");

        // Simulated search results – in production, call a real search API.
        var results = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase)
        {
            ["quantum computing"] =
            [
                "Quantum computing uses qubits that can exist in superposition, enabling parallel computation. Major players include IBM, Google, and Microsoft.",
                "In 2024, IBM unveiled its 1,121-qubit Condor processor. Google's Willow chip demonstrated quantum error correction below threshold.",
                "Potential applications include drug discovery, cryptography, optimization problems, and materials science. Current machines are 'noisy intermediate-scale quantum' (NISQ) devices.",
                "Microsoft's topological qubit approach aims for inherently more stable qubits. Azure Quantum offers cloud access to multiple quantum hardware providers."
            ],
            ["artificial intelligence"] =
            [
                "Modern AI is dominated by large language models (LLMs) built on the Transformer architecture introduced in 2017.",
                "Key trends include multimodal models, AI agents, retrieval-augmented generation (RAG), and smaller efficient models.",
                "Safety and alignment research is a growing field, with techniques like RLHF and constitutional AI guiding model behavior.",
                "AI is being applied across healthcare, finance, software engineering, scientific research, and creative industries."
            ],
            ["climate change"] =
            [
                "Global average temperatures have risen ~1.2°C above pre-industrial levels. The Paris Agreement targets limiting warming to 1.5°C.",
                "Renewable energy capacity surpassed 500 GW of new installations in 2023, led by solar photovoltaics.",
                "Carbon capture and storage (CCS) technologies are scaling up, with direct air capture plants operational in Iceland and the US.",
                "Ocean acidification, biodiversity loss, and extreme weather events are accelerating impacts of climate change."
            ]
        };

        // Match any key that appears in the query.
        foreach (var kvp in results)
        {
            if (query.Contains(kvp.Key, StringComparison.OrdinalIgnoreCase))
            {
                return string.Join("\n\n", kvp.Value.Select((r, i) => $"[{i + 1}] {r}"));
            }
        }

        return $"[1] {query} is an active area of research with many recent developments.\n\n"
             + $"[2] Experts suggest {query} will have significant impact in the coming decade.\n\n"
             + $"[3] Several organizations and governments are investing heavily in {query}.";
    }

    [Description("Save a research note under a topic heading. Use this to record key findings.")]
    public static string SaveNote(
        [Description("The topic or heading for the note")] string topic,
        [Description("The content of the note")] string content)
    {
        _notes.Add((topic, content));
        Console.WriteLine($"  📝  Note saved under \"{topic}\"");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Topic} ---\n{n.Note}"));
    }
}

