2. using OpenAI;
3. 
4. var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
5.     ?? Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
6.     ?? "demo-key";
7. 
8. var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
9. 
10. IChatClient chatClient = new OpenAIClient(apiKey)
11.     .GetChatClient(modelId)
12.     .AsIChatClient();
13. 
14. var tools = new[]
15. {
16.     AIFunctionFactory.Create(ResearchTools.WebSearch),
17.     AIFunctionFactory.Create(ResearchTools.SaveNote),
18.     AIFunctionFactory.Create(ResearchTools.GetNotes),
19. };
20. 
21. var chatOptions = new ChatOptions
22. {
23.     Tools = [.. tools],
24.     ToolMode = ChatToolMode.Auto
25. };
26. 
27. var systemPrompt = """
28.     You are a research agent. Your job is to research a topic thoroughly and produce
29.     a clear summary. Follow these steps:
30.     1. Use the WebSearch tool to find information about the topic.
31.     2. Use the SaveNote tool to record key findings as you go.
32.     3. Perform additional searches to fill gaps or explore subtopics.
33.     4. Use GetNotes to review everything you have collected.
34.     5. Finally, produce a well-structured summary of your research.
35.     Be thorough but concise. Cite key facts and figures where available.
36.     """;
37. 
38. var topic = args.Length > 0
39.     ? string.Join(' ', args)
40.     : "quantum computing";
41. 
42. Console.WriteLine($"🤖 Research Agent Starting...");
43. Console.WriteLine($"📚 Topic: {topic}\n");
44. 
45. List<ChatMessage> messages =
46. [
47.     new(ChatRole.System, systemPrompt),
48.     new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
49. ];
50. 
51. // Agent loop: keep calling the model until it produces a final answer with no tool calls.
52. const int maxIterations = 15;
53. for (var i = 0; i < maxIterations; i++)
54. {
55.     var response = await chatClient.GetResponseAsync(messages, chatOptions);
56. 
57.     // Append the full response (including any tool-call content) to the conversation.
58.     messages.AddMessages(response);
59. 
60.     // Check whether the model invoked any tools.
61.     var functionCalls = response.Messages
62.         .SelectMany(m => m.Contents)
63.         .OfType<FunctionCallContent>()
64.         .ToList();
65. 
66.     if (functionCalls.Count == 0)
67.     {
68.         // No tool calls – the model produced its final answer.
69.         var answer = response.Messages
70.             .SelectMany(m => m.Contents)
71.             .OfType<TextContent>()
72.             .LastOrDefault();
73. 
74.         Console.WriteLine("\n════════════════════════════════════════════");
75.         Console.WriteLine("  RESEARCH SUMMARY");
76.         Console.WriteLine("════════════════════════════════════════════\n");
77.         Console.WriteLine(answer?.Text ?? "(no summary produced)");
78.         break;
79.     }
80. 
81.     // Execute each tool call and feed results back to the model.
82.     foreach (var fc in functionCalls)
83.     {
84.         var tool = tools.FirstOrDefault(t => t.Name == fc.Name);
85.         if (tool is null)
86.         {
87.             messages.Add(new ChatMessage(ChatRole.Tool,
88.                 [new FunctionResultContent(fc.CallId, fc.Name, "Unknown tool.")]));
89.             continue;
90.         }
91. 
92.         var result = await tool.InvokeAsync(fc.Arguments);
93.         messages.Add(new ChatMessage(ChatRole.Tool,
94.             [new FunctionResultContent(fc.CallId, fc.Name, result)]));
95.     }
96. }
97. 
98. Console.WriteLine("\n✅ Research complete.");
99.

